import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"坤","description":"周易集解 - 坤","frontmatter":{"title":"坤","description":"周易集解 - 坤"},"headers":[],"relativePath":"classics/jijie/002.md","filePath":"classics/jijie/002.md"}'),l={name:"classics/jijie/002.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="坤" tabindex="-1">坤 <a class="header-anchor" href="#坤" aria-label="Permalink to “坤”">​</a></h1><h2 id="坤-1" tabindex="-1">坤 <a class="header-anchor" href="#坤-1" aria-label="Permalink to “坤”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>坤，元亨，利牝馬之貞。君子有攸往，先迷，後得，主利。西南得朋，東北喪朋，安貞吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>乾寶曰：陰氣之始，婦德之常，故稱元。與乾合德，故稱亨。行天者莫若龍，行地者莫若馬，故乾以龍繇，坤以馬象也。坤，陰類，故稱「利牝馬之貞」矣。</p><p>虞翻曰：謂陰極陽生，乾流坤形，坤含光大，凝乾之元，終於坤亥，出乾初子，品物咸亨，故元亨也。坤為牝，震為馬，初動得正，故「利牝馬之貞」矣。</p><p>盧氏曰：坤，臣道也、妻道也。後而不先，先則迷失道矣，故曰先迷。陰以陽為主，當後而順之，則利。故曰「後得主利」。</p><p>《九家易》曰：坤為牝，為迷。</p><p>崔憬曰：妻道也。西方坤兌，南方巽離，二方皆陰，與坤同類，故曰西南得朋。東方艮震，北方乾坎，二方皆陽，與坤非類，故曰東北喪朋。以喻在室得朋，猶迷於失道；出嫁喪朋，乃順而得常。安於承天之正，故言「安貞吉」也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含宏光大，品物咸亨。牝馬地類，行地無疆，柔順利貞。君子攸行。先迷失道，後順得常。西南得朋，乃與類行。東北喪朋，乃終有慶。東北喪朋，乃終有慶。安貞之吉，應地無疆。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>《九家易》曰：謂乾氣至坤，萬物資受而以生也。坤者純陰，配乾生物，亦善之始，地之象也，故又歎言至美。</p><p>《九家易》曰：謂萬一千五百二十策，皆受始於乾，由坤而生也。策生於坤，猶萬物成形，出乎地也。</p><p>劉瓛曰：萬物資生於地，故地承天而生也。</p><p>蜀才曰：坤以廣厚之德，載含萬物，無有窮竟也。</p><p>蜀才曰：天有無疆之德，而坤合之，故雲「德合無疆」也。</p><p>荀爽曰：乾二居坤五為含，坤五居乾二為弘，坤初居乾四為光，乾四居坤初為大也。</p><p>荀爽曰：天地交，萬物生，故咸亨。</p><p>崔憬曰：含育萬物為弘，光華萬物為大，動植各遂其性，故言品物咸亨也。</p><p>侯果曰：地之所以含弘物者，以其順而承天也。馬之所以行地遠者，以其柔而伏人也。而又牝馬，順之至也。誡臣子當至順，故作易者取象焉。</p><p>《九家易》曰：謂坤爻本在柔順陰位，則利正之。乾則陽爻來據之，故曰君子攸行。</p><p>何妥曰：陰道惡先，故先致迷失。後順於主，則保其常慶也。</p><p>虞翻曰：謂陽得其類，月朔至望，從震至乾，與時偕行，故乃與類行。</p><p>虞翻曰：陽喪滅坤，坤終復生，謂月三日震象出庚，故乃終有慶。此指說易道陰陽消息之大要也。謂陽月三日，變而成震，出庚。至月八日成兌，見丁。庚西丁南，故西南得朋。謂二陽為朋，故兌「君子以朋友講習」。《文言》曰：敬義立而德不孤。《彖》曰：乃與類行。二十九日，消乙入坤，滅藏於癸，乙東癸北，故東北喪朋。謂之以坤滅乾，坤為喪故也。</p><p>馬君雲：孟秋之月，陰氣始著，而坤之位，同類相得，故西南得朋。孟春之月，陽氣始著，陰始從陽，失其黨類，故東北喪朋。失之甚矣。而荀君以為陰起於午，至申三陰，得坤一體，故曰西南得朋。陽起於子，至寅三陽，喪坤一體，故曰東北喪朋。就如荀說，從午至申，經當言南西得朋；子至寅，當言北東喪朋。以乾變坤，而言喪朋，經以乾卦為喪耶？此何異於馬也。</p><p>虞翻曰：坤道至靜，故安；復初得正，故貞吉。</p><p>虞翻曰：震為應。陽正於初，以承坤陰；地道應，故應地無疆。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：地勢坤，君子以厚德載物。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：地形不順矣。</p><p>宋衷曰：地有上下九等之差，故以形勢言其性也。</p><p>虞翻曰：勢，力也。君子謂乾，陽為德動。在坤下，君子之德車。故「厚德載物」。老子曰：勝人者有力也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，履霜，堅冰至。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>乾寶曰：重陰，故稱六。剛柔相推，故生變。佔變，故有爻。《繫》曰：爻者，言乎變者也。故《易》、《繫辭》皆稱九、六也。陽數奇，陰數偶，是以乾用一也。坤用二也。陰氣在初，五月之時，自姤來也。陰氣始動乎三泉之下，言陰氣之動矣。則必至於履霜，履霜則必至於堅冰，言有漸也。藏器於身，貴其俟時，故陽在潛龍，戒以勿用。防禍之原。欲其先幾，故陰在三泉，而顯以履霜也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：履霜堅冰，陰始凝也。馴致其道，至堅冰也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>九家易》曰：霜者，乾之命也。堅冰者，陰功成也。謂坤初六之乾四，履乾命令而成堅冰也。此卦本乾，陰始消，陽起於此爻，故履霜也。馴，猶順也，言陽順陰之性，成堅冰矣。初六始姤，姤為五月。盛夏而言堅冰，五月陰氣始生地中，言始於微霜，終至堅冰，以明漸順至也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，直方大。不習無不利。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：大者，陽也。二應五，五下動之，則應陽出，直布陽於四方。</p><p>荀爽曰：物唱乃和，不敢先有所習。陽之所唱，從而和之，無不利也。</p><p>乾寶曰：陰氣在二，六月之時，自遯來也。陰出地上，佐陽成物，臣道也，妻道也。臣之事君，妻之事夫，義成者也。臣貴其直，義尚其方，地體其大，故曰直方大。士該九德，然後可以從王事；女躬四教，然後可以配君子。道成於我，而用之於彼。不方以仕學為政，不方以嫁學為婦。故曰不習無不利也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六二之動，直以方也。不習無不利，地道光也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：謂陽下動，應之，則直而行，布陽氣，動於四方也。</p><p>乾寶曰：女德光於夫，士德光於國也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，含章可貞。或從王事，無成有終。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：貞，正也。以陰包陽，故含章。三失位，發得正，故可貞也。</p><p>虞翻曰：謂三已發成泰，乾為主，坤為事，震為從，故或從王事。地道無成而有終，故無成有終。</p><p>乾寶曰：陰氣在三，七月之時，自否來也。陽降在四，三公位也。陰升在三，三公事也。上失其權，位在諸侯。坤體既具，陰黨成群。君弱臣強，戒在二國。唯文德之臣，然後可以遭之，運而不失其柔順之正。坤為文，坤象既成，故曰含章可貞。此蓋平襄之王垂拱以賴晉鄭之輔也。苟利社稷，專之則可，故曰或從王事。遷都誅親，疑於專命，故亦或之。失後順之節，故曰無成。終於濟國安民，故曰有終。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：含章可貞，以時發也。或從王事，知光大也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：陽命則發，非時則含也。</p><p>乾寶曰：位彌高，德彌廣也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，括囊，無咎，無譽。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：括，結也。謂泰反成否。坤為囊，艮為手，巽為繩，故括囊在外多咎也。得位承五，繫於包桑，故無咎。陰在二多譽，而遠在四，故無譽。</p><p>乾寶曰：陰氣在四，八月之時，自觀來也。天地將閉，賢人必隱，懷智苟容，以觀時釁，此蓋甯戚、籧瑗與時捲舒之爻也。不艱其身，則無咎。功業不建，故無譽也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：括囊，無咎，慎不害也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>盧氏曰：慎言則無咎也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，黃裳，元吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>乾寶曰：陰氣在五，九月之時，自剝來也。剝者，反常道也。黃，中之色。裳，下之飾。元，善之長也。中美能黃，上美為元，下美則裳。陰登於五，柔居尊位，若成昭之主，周霍之臣也。百官總已，專斷萬幾，雖情體信順，而貌近僣疑，周公其猶病諸。言必忠信，行必篤敬，然後可以取信於神明，無尤於四海也。故曰「黃裳，元吉」也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：黃裳，元吉，文在中也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>王肅曰：坤為文，五在中，故曰文在中也。</p><p>乾寶曰：當總已之任，處僭疑之間，而能終元吉之福者，由文德在中也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，龍戰於野，其血玄黃。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>荀爽曰：消息之位，坤在於亥。下在伏乾，為其兼於陽，故稱龍也。</p><p>《九家易》曰：實本坤體，未離其類，故稱血焉。血以喻陰也。玄黃，天地之雜，言乾坤合居也。</p><p>侯果曰：坤，十月卦也。乾位西北，又當十月。陰窮於亥，窮陰薄陽，所以戰也。故《說卦》雲「戰乎乾」是也。六稱龍者，陰盛似龍，故稱龍也。</p><p>乾寶曰：陰在上六，十月之時也。爻終於酉，而卦成於乾。乾體純剛，不堪陰盛，故曰龍戰。戌亥，乾之都也，故稱龍焉。陰德過度，以逼乾戰。郭外曰郊，郊外曰野。坤位未申之維，而氣溢酉戌之間，故曰於野。未離陰類，故曰血。陰陽色雜，故曰玄黃。言陰陽離則異氣，合則同功。君臣夫妻，其義一也。故文王之忠於殷，抑參二之強，以事獨夫之紂。蓋欲彌縫其闕。而匡救其惡，以祈殷命，以濟生民也。紂遂長惡不悛，天命殛之。是以至於武王，遂有牧野之事，是其義也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：龍戰於野，其道窮也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：天道窮，至於陰陽和薄也。君德窮，至於攻戰受誅也。柔順窮，至於用權變矣。</p><h2 id="用六" tabindex="-1">用六 <a class="header-anchor" href="#用六" aria-label="Permalink to “用六”">​</a></h2><p>用六，利永貞。</p><h2 id="用六注" tabindex="-1">用六注 <a class="header-anchor" href="#用六注" aria-label="Permalink to “用六注”">​</a></h2><p>乾寶曰：陰體其順，臣守其柔。所以秉義之和，履貞之乾。唯有推變，終歸於正。是周公始於負扆南面，以先王道，卒於復子明闢，以終臣節，故曰利永貞也。</p><h2 id="象-7" tabindex="-1">象 <a class="header-anchor" href="#象-7" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：用六永貞，以大終也。</p><h2 id="象傳注-7" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-7" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：用六，妻道也，臣道也，利在長正矣。不長正，則不能大終陽事也。</p>',102)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
